<?php
declare(strict_types=1);
require __DIR__ . '/../includes/db.php';
if (empty($_SESSION['blog_admin_id'])) { header('Location: login.php'); exit; }
if (($_SESSION['blog_admin_role'] ?? 'admin') !== 'admin') { http_response_code(403); exit('Bạn không có quyền xem đối soát nhuận bút.'); }
function crpd_h($v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$id=(int)($_GET['id']??0);
$q=$pdo->prepare('SELECT * FROM contributor_reward_periods WHERE id=?');$q->execute([$id]);$period=$q->fetch();
if(!$period){http_response_code(404);exit('Không tìm thấy kỳ nhuận bút.');}
$q=$pdo->prepare("SELECT i.*,m.display_name,m.email,r.payment_status,r.paid_at,r.created_at reward_created
 FROM contributor_reward_period_items i JOIN members m ON m.id=i.member_id
 LEFT JOIN contributor_rewards r ON r.id=i.reward_id WHERE i.period_id=? ORDER BY i.total_amount DESC,m.display_name");
$q->execute([$id]);$items=$q->fetchAll();
$pending=0.0;$paid=0.0;$pendingCount=0;$paidCount=0;
foreach($items as $it){if(($it['payment_status']??'pending')==='paid'){$paid+=(float)$it['total_amount'];$paidCount++;}else{$pending+=(float)$it['total_amount'];$pendingCount++;}}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đối soát kỳ <?=crpd_h($period['period_key'])?> | Truyện Đêm</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin-white.css?v=20261121-layout2"><link rel="stylesheet" href="../css/admin-cms.css?v=20261121-cms1"><style>
.rpd-wrap{max-width:1200px;margin:26px auto;padding:0 16px 40px}.rpd-card{background:#fff;border:1px solid #e5e9f0;border-radius:16px;padding:20px;margin:16px 0;box-shadow:0 8px 28px #17243a0a}.rpd-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.rpd-head h1,.rpd-card h2{margin:0;color:#172033}.rpd-muted{color:#718096;line-height:1.6}.rpd-back{color:#5546c8;text-decoration:none;font-weight:700}.rpd-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:18px}.rpd-stat{background:#f7f8fc;border:1px solid #edf0f5;border-radius:12px;padding:14px}.rpd-stat span{display:block;color:#718096;font-size:12px}.rpd-stat strong{display:block;margin-top:6px;color:#172033;font-size:20px}.rpd-scroll{overflow-x:auto}.rpd-table{width:100%;border-collapse:collapse;min-width:920px}.rpd-table th,.rpd-table td{padding:12px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px;vertical-align:top}.rpd-table th{color:#718096;white-space:nowrap}.rpd-table small{display:block;color:#8490a2;margin-top:4px}.rpd-status{display:inline-block;padding:5px 9px;border-radius:20px;font-size:12px;font-weight:700;background:#fff4df;color:#895b08}.rpd-status.paid{background:#e8f7ee;color:#17643a}.rpd-note{background:#f4f6fb;border-radius:10px;padding:12px;color:#596579;font-size:13px;line-height:1.6}@media(max-width:700px){.rpd-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.rpd-card{padding:15px}.rpd-stat strong{font-size:17px}}
</style></head><body class="admin-theme"><?php include __DIR__.'/_nav.php';?><main class="rpd-wrap"><section class="rpd-card"><div class="rpd-head"><div><h1>Đối soát nhuận bút tháng <?=crpd_h($period['period_key'])?></h1><p class="rpd-muted">Chi tiết phân bổ theo từng cộng tác viên và tình trạng thanh toán.</p></div><a class="rpd-back" href="contributor-reward-periods.php">← Quay lại các kỳ</a></div><div class="rpd-stats"><div class="rpd-stat"><span>Doanh thu thuần</span><strong><?=number_format((float)$period['net_revenue'],0,',','.')?>đ</strong></div><div class="rpd-stat"><span>Tổng quỹ</span><strong><?=number_format((float)$period['total_fund'],0,',','.')?>đ</strong></div><div class="rpd-stat"><span>Đã thanh toán</span><strong><?=number_format($paid,0,',','.')?>đ</strong></div><div class="rpd-stat"><span>Còn chờ thanh toán</span><strong><?=number_format($pending,0,',','.')?>đ</strong></div></div><p class="rpd-muted">Trạng thái kỳ: <span class="rpd-status <?=$period['status']==='paid'?'paid':''?>"><?= $period['status']==='paid'?'Đã thanh toán':($period['status']==='cancelled'?'Đã hủy':'Đang đối soát') ?></span> · <?=count($items)?> CTV · <?=$paidCount?> đã trả · <?=$pendingCount?> đang chờ</p></section>
<section class="rpd-card"><h2>Bảng chi tiết theo CTV</h2><p class="rpd-muted">Số tiền đã điều chỉnh theo giới hạn quỹ của tháng. Muốn xác nhận trả tiền, vào mục Nhuận bút CTV.</p><div class="rpd-scroll"><table class="rpd-table"><thead><tr><th>Cộng tác viên</th><th>Tác phẩm duyệt</th><th>Lượt đọc/nghe hợp lệ</th><th>Phí tác phẩm</th><th>Thưởng lượt đọc</th><th>Tổng nhuận bút</th><th>Thanh toán</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><strong><?=crpd_h($it['display_name'])?></strong><small>#<?=(int)$it['member_id']?> · <?=crpd_h($it['email'])?></small></td><td><?=(int)$it['approved_works']?><small>Gốc: <?=number_format((float)$it['publication_raw'],0,',','.')?>đ</small></td><td><?=number_format((int)$it['qualified_reads'],0,',','.')?><small>Gốc: <?=number_format((float)$it['reading_raw'],0,',','.')?>đ</small></td><td><?=number_format((float)$it['publication_amount'],0,',','.')?>đ</td><td><?=number_format((float)$it['reading_amount'],0,',','.')?>đ</td><td><strong><?=number_format((float)$it['total_amount'],0,',','.')?>đ</strong></td><td><?php if(($it['payment_status']??'pending')==='paid'):?><span class="rpd-status paid">Đã thanh toán</span><small><?=!empty($it['paid_at'])?crpd_h(date('d/m/Y',strtotime($it['paid_at']))):''?></small><?php else:?><span class="rpd-status">Chờ thanh toán</span><small>Mở mục Nhuận bút CTV để xác nhận</small><?php endif;?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="7">Kỳ này chưa phát sinh khoản nhuận bút phải trả.</td></tr><?php endif;?></tbody></table></div><p class="rpd-note">Quỹ thành tích: <?=number_format((float)$period['achievement_pool'],0,',','.')?>đ (đang được giữ riêng, chưa phân bổ tự động). Kỳ chỉ chuyển sang “Đã thanh toán” khi tất cả khoản nhuận bút được tạo trong kỳ đã thanh toán.</p><p><a class="rpd-back" href="contributor-rewards.php">Mở quản lý thanh toán CTV →</a></p></section></main></body></html>